-- Stage6: report/repertoire tables plus optional structured fields on old submission/comment rows. No old field or row is rewritten.
CREATE TABLE growth_repertoire(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,student_id TEXT NOT NULL,name TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('learning','done')),start_date TEXT,completed_date TEXT,image_ids_json TEXT NOT NULL DEFAULT '[]',created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id));
